import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

public class DaysToNewYear {
    public static void main(String[] args) {
        LocalDate today      = LocalDate.now();
        LocalDate nextNewYear = LocalDate.of(today.getYear() + 1, 1, 1);
        long daysUntil = ChronoUnit.DAYS.between(today, nextNewYear);
        System.out.println("Today        : " + today);
        System.out.println("Next New Year: " + nextNewYear);
        System.out.println("Days until   : " + daysUntil);
    }
}
// Uses java.time.LocalDate for immutable, type-safe date representation
// Uses ChronoUnit.DAYS.between() for accurate day counting (handles leap years)
// today.getYear() + 1 ensures we always target the NEXT year, not the current

