import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class StudentFilter {
    public static void main(String[] args) {
        List<String> names = new ArrayList<>(
            List.of("Raj", "Ananya", "Zoe", "Priya", "Bo"));
        System.out.println("Original : " + names);

        Collections.sort(names);  // Alphabetical sort
        System.out.println("Sorted   : " + names); // [Ananya, Bo, Priya, Raj, Zoe]

        names.removeIf(name -> name.length() < 4); // Remove short names
        System.out.println("Filtered : " + names); // [Ananya, Priya]
    }
}
// Collections.sort() — in-place sort from java.util
// removeIf() — List method using Predicate (lambda) — removes Bo, Raj, Zoe (< 4 chars)

