import java.math.BigDecimal;
import java.math.MathContext;
import java.math.RoundingMode;

public class CompoundInterest {
    public static void main(String[] args) {
        BigDecimal principal = new BigDecimal("10000");
        BigDecimal rate      = new BigDecimal("0.085"); // 8.5% = 0.085
        int        years     = 3;

        // (1 + r)^n using MathContext for precision
        BigDecimal factor = BigDecimal.ONE.add(rate); // 1.085
        BigDecimal amount = principal;
        for (int i = 0; i < years; i++) {
            amount = amount.multiply(factor); // Compound each year
        }
        amount = amount.setScale(2, RoundingMode.HALF_UP);

        BigDecimal interest = amount.subtract(principal);
        System.out.println("Principal : ₹" + principal);
        System.out.println("Rate      : 8.5% p.a.");
        System.out.println("Years     : " + years);
        System.out.println("Amount    : ₹" + amount);   // ₹12772.85
        System.out.println("Interest  : ₹" + interest); // ₹2772.85
    }
}
